// BAD: Blocks a thread pool thread for the entire DB call
public string GetDataSync()
{
    return _dbContext.Orders
        .Where(o => o.Status == "Pending")
        .ToListAsync()
        .Result; // Blocks!
}

// GOOD: Async all the way down
public async Task<List<Order>> GetDataAsync()
{
    return await _dbContext.Orders
        .Where(o => o.Status == "Pending")
        .ToListAsync();
}

// Set minimum threads in Program.cs
ThreadPool.SetMinThreads(
    workerThreads: 100,
    completionPortThreads: 100);

// Restore default behavior when the app shuts down
var originalMin = ThreadPool.GetMinThreads(out var originalMinIOCP);
// ... later on shutdown ...
ThreadPool.SetMinThreads(originalMin, originalMinIOCP);
